@dataclass(frozen=True)
class EventSpec:
    category: str
    name: str
    event_id: str
    uncertain_id: bool
    send_sites: tuple
    functions: tuple
    networked: bool
    kept: bool
    fields: tuple
    counts: tuple

    @property
    def scope(self):
        return "all seats" if self.networked else "local"


@lru_cache(maxsize=1)
def load_catalog():
    category = ""
    events = []
    seen = set()
    for line in SOURCE_MARKDOWN.splitlines():
        if line.startswith("## "):
            category = line[3:].strip()
        if not line.startswith("| " + chr(96)):
            continue
        cells = [value.strip() for value in line.strip().strip("|").split("|")]
        if len(cells) != 8 or not category:
            raise ValueError("Invalid event table row")
        raw_name, event_id, sites, functions, network, kept, field_text, counts = cells
        name = raw_name.strip(chr(96))
        event_id = event_id.strip(chr(96))
        if name in seen or not re.fullmatch(r"0x[0-9a-fA-F]{8}\??", event_id):
            raise ValueError("Duplicate name or invalid ID: " + name)
        fields = []
        for item in field_text.split():
            if ":" not in item:
                raise ValueError("Malformed field: " + name)
            key, field_type = item.split(":", 1)
            if field_type not in ("entity", "bool", "int", "float", "string"):
                raise ValueError("Unsupported field type: " + field_type)
            fields.append((key, field_type))
        if network not in ("yes", "local"):
            raise ValueError("Invalid network scope: " + name)
        seen.add(name)
        events.append(EventSpec(
            category, name, event_id, event_id.endswith("?"),
            tuple(re.findall(r"0x[0-9a-fA-F]+", sites)),
            tuple(re.findall(r"0x[0-9a-fA-F]+", functions)),
            network == "yes", kept == "yes", tuple(fields),
            tuple(int(x.strip()) for x in counts.split("/") if x.strip())))
    if not events:
        raise ValueError("No events in developer catalog")
    # V3 CSV is the comprehensive developer export. Preserve the familiar
    # curated groups for 357 events, and add the remaining 177 from the scan.
    # An empty CSV ID is explicitly unresolved, never a callable guessed hash.
    import csv
    import io
    from developer_events_all_v3 import SOURCE_CSV
    curated = {event.name: event for event in events}
    complete = []
    for row in csv.DictReader(io.StringIO(SOURCE_CSV)):
        name = row['event']
        original = curated.get(name)
        event_id = row['id'].strip()
        uncertain = not event_id or event_id.endswith('?')
        fields = []
        for token in row['fields'].split():
            if ':' not in token:
                raise ValueError('Malformed field of ' + name)
            key, kind = token.split(':', 1)
            if kind not in ('entity','string','bool','int','float'):
                raise ValueError('Unknown V3 field type: ' + kind)
            fields.append((key, kind))
        complete.append(EventSpec(
            original.category if original else 'Additional game events',
            name, event_id or 'unresolved', uncertain,
            tuple(re.findall(r'0x[0-9a-fA-F]+',row['send_site_rvas'])),
            tuple(re.findall(r'0x[0-9a-fA-F]+',row['send_funcs'])),
            row['net'] == 'networked', row['kept'] == 'kept',
            tuple(fields), original.counts if original else ()))
    if len(complete) != 534 or len({e.name for e in complete}) != len(complete):
        raise ValueError('Comprehensive event catalog is incomplete.')
    return tuple(complete)


def filter_catalog(query="", category="All categories", scope="All seats / local",
                   recorder="All events"):
    needle = query.strip().casefold()
    return tuple(e for e in load_catalog()
                 if category == "All categories" or e.category == category
                 if scope == "All seats / local" or e.scope == scope
                 if recorder == "All events" or
                    (recorder == "Kept by recorder" and e.kept) or
                    (recorder == "Not kept" and not e.kept) or
                    (recorder == "Uncertain ID" and e.uncertain_id)
                 if not needle or needle in
                    (e.name + " " + e.event_id + " " + e.category + " " +
                     " ".join(k for k, _ in e.fields)).casefold())


def _parse_value(raw, kind):
    if raw is None or str(raw).strip() == "":
        return None
    value = str(raw).strip()
    if len(value) > 512:
        raise ValueError("Value is too long")
    if kind == "bool":
        if value.lower() in ("true", "1", "yes", "on"):
            return True
        if value.lower() in ("false", "0", "no", "off"):
            return False
        raise ValueError("Expected true/false")
    if kind == "int":
        try:
            return int(value, 0)
        except ValueError as exc:
            raise ValueError("Expected an integer") from exc
    if kind == "float":
        try:
            num = float(value)
        except ValueError as exc:
            raise ValueError("Expected a float") from exc
        if not math.isfinite(num):
            raise ValueError("Float must be finite")
        return num
    if kind == "entity" and len(value) > 128:
        raise ValueError("Entity reference is too long")
    return value


def make_fixture(event, values=None):
    """Produce JSON-ready offline test data, never a live event dispatch."""
    if not isinstance(event, EventSpec):
        raise TypeError("Select a known event")
    values = values or {}
    fields, missing = {}, []
    for key, kind in event.fields:
        try:
            val = _parse_value(values.get(key), kind)
        except ValueError as exc:
            raise ValueError(key + ": " + str(exc)) from exc
        if val is None:
            missing.append(key)
        else:
            fields[key] = val
    return {"format": "evolve-local-event-fixture-v1",
            "source": CATALOG_VERSION, "build": SOURCE_BUILD,
            "event": event.name, "id": event.event_id,
            "id_uncertain": event.uncertain_id, "scope": event.scope,
            "fixture_only": True, "fields": fields,
            "unfilled_fields": missing}


def inspect_capture(text, max_bytes=8 * 1024 * 1024, max_records=50000):
    """Read bounded user-supplied JSON or JSONL from an event-tap capture."""
    if len(text.encode("utf-8")) > max_bytes:
        raise ValueError("Capture exceeds 8 MiB")
    try:
        rows = json.loads(text)
    except json.JSONDecodeError:
        rows = [json.loads(line) for line in text.splitlines() if line.strip()]
    if isinstance(rows, dict):
        rows = rows.get("events", [rows])
    if not isinstance(rows, list) or len(rows) > max_records:
        raise ValueError("Expected up to 50,000 JSON event objects")
    names = {e.name: e for e in load_catalog()}
    ids = {e.event_id.lower(): e for e in load_catalog()
           if not e.uncertain_id}
    matched = Counter()
    unknown = 0
    for record in rows:
        if not isinstance(record, dict):
            unknown += 1
            continue
        key = record.get("event") or record.get("event_name") or record.get("name")
        if isinstance(key, dict):
            key = key.get("name")
        candidate = names.get(str(key)) if key is not None else None
        identifier = record.get("event_id") or record.get("id")
        if candidate is None and identifier is not None:
            if isinstance(identifier, int):
                identifier = "0x%08x" % identifier
            candidate = ids.get(str(identifier).lower())
        if candidate:
            matched[candidate.name] += 1
        else:
            unknown += 1
    return {"records": len(rows), "matched": sum(matched.values()),
            "unknown": unknown, "counts": dict(matched)}
